GlobalDataStore:IncrementAsync.example:
-- Script in ServerScriptService
local DataStoreService = game:GetService("DataStoreService")
local Players = game:GetService("Players")
local stats = DataStoreService:GetDataStore("GameStats")

Players.PlayerAdded:Connect(function()
	local ok, total = pcall(function()
		return stats:IncrementAsync("TotalVisits", 1)
	end)
	if ok then print("Total visits ever:", total) end
end)

GlobalDataStore:UpdateAsync.example:
-- Script in ServerScriptService
local DataStoreService = game:GetService("DataStoreService")
local store = DataStoreService:GetDataStore("PlayerCoins")

local ok, newValue = pcall(function()
	return store:UpdateAsync("User_12345", function(current)
		return (current or 0) + 10 -- add 10 coins
	end)
end)
print(ok, newValue)
